type Json = unknown;

function isObject(val: Json): val is Record<string, Json> {
  return typeof val === "object" && val !== null && !Array.isArray(val);
}

function canonicalize(val: Json): string {
  if (Array.isArray(val)) {
    return "[" + val.map(canonicalize).join(",") + "]";
  }
  if (isObject(val)) {
    const keys = Object.keys(val).sort();
    return (
      "{" +
      keys
        .map((k) => JSON.stringify(k) + ":" + canonicalize(val[k]))
        .join(",") +
      "}"
    );
  }
  return JSON.stringify(val);
}

function dedupe(arr: Json[]): Json[] {
  const seen = new Set<string>();
  const result: Json[] = [];
  for (const item of arr) {
    const key = canonicalize(item);
    if (!seen.has(key)) {
      seen.add(key);
      result.push(item);
    }
  }
  return result;
}

function deepMerge(a: Json, b: Json): Json {
  if (Array.isArray(a) && Array.isArray(b)) {
    return dedupe([...a, ...b]);
  }
  if (isObject(a) && isObject(b)) {
    const merged: Record<string, Json> = {};
    const keys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);
    for (const key of keys) {
      const inA = key in a;
      const inB = key in b;
      if (inA && inB) {
        merged[key] = deepMerge(a[key], b[key]);
      } else if (inA) {
        merged[key] = a[key];
      } else {
        merged[key] = b[key];
      }
    }
    return merged;
  }
  return b;
}

function sortKeys(val: Json): Json {
  if (Array.isArray(val)) {
    return val.map(sortKeys);
  }
  if (isObject(val)) {
    const sorted: Record<string, Json> = {};
    for (const key of Object.keys(val).sort()) {
      sorted[key] = sortKeys(val[key]);
    }
    return sorted;
  }
  return val;
}

