    // Both objects: merge recursively
    if let aDict = a as? [String: Any], let bDict = b as? [String: Any] {
        var result: [String: Any] = aDict
        for (key, bValue) in bDict {
            if let aValue = result[key] {
                result[key] = deepMerge(aValue, bValue)
            } else {
                result[key] = bValue
            }
        }
        return result
