fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    current.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            } else {
                current.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == ',' {
            fields.push(current.clone());
            current.clear();
        } else {
            current.push(c);
        }
    }
    fields.push(current);
    fields
}

fn format_number(n: i64) -> String {
    let negative = n < 0;
    let val = if negative { -n } else { n };
    let s = val.to_string();
    let bytes = s.as_bytes();
    let len = bytes.len();
    let mut result = String::new();
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*b as char);
    }
    if negative {
        result.insert(0, '-');
    }
    result
}

fn format_decimal(avg: f64) -> String {
    let negative = avg < 0.0;
    let abs = if negative { -avg } else { avg };
    let total_cents = (abs * 100.0).round() as i64;
    let int_part = total_cents / 100;
    let cent_part = total_cents % 100;
    format!("{}.{:02}", format_number(int_part), cent_part)
}

fn parse_salary(s: &str) -> i64 {
    let cleaned: String = s.chars().filter(|c| *c != '$' && *c != ',').collect();
    cleaned
        .trim()
        .parse::<f64>()
        .expect("Invalid salary")
        .round() as i64
}

