static char *xstrdup(const char *s) {
    size_t n = strlen(s) + 1;
    char *p = malloc(n ? n : 1);
    if (p) memcpy(p, s, n);
    return p;
}

static Counter *find_counter(Counter *arr, int n, const char *name) {
    for (int i = 0; i < n; i++)
        if (strcmp(arr[i].name, name) == 0) return &arr[i];
    return NULL;
}

static void add_level(const char *name) {
    Counter *c = find_counter(levels, nlevels, name);
    if (c) { c->count++; return; }
    if (nlevels == caplevels) {
        caplevels = caplevels ? caplevels * 2 : 16;
        levels = realloc(levels, (size_t)caplevels * sizeof(Counter));
    }
    levels[nlevels].name = xstrdup(name);
    levels[nlevels].count = 1;
    nlevels++;
}

