    with open(graph_path, "r") as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    # Build adjacency list for an undirected graph
    adj = {node: [] for node in nodes}
    for edge in edges:
        frm = edge["from"]
        to = edge["to"]
        weight = edge["weight"]
        if frm not in adj:
            adj[frm] = []
        if to not in adj:
            adj[to] = []
        adj[frm].append((to, weight))
        adj[to].append((frm, weight))  # undirected: add reverse edge

    start = "A"

    # Dijkstra's algorithm
    dist = {node: float("inf") for node in nodes}
    if start not in dist:
        dist[start] = 0
    else:
        dist[start] = 0

    visited = set()
    pq = [(0, start)]

    while pq:
        d, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        for neighbor, weight in adj.get(node, []):
            nd = d + weight
            if nd < dist.get(neighbor, float("inf")):
                dist[neighbor] = nd
                heapq.heappush(pq, (nd, neighbor))

    # Output
    print("=== Shortest Paths from A ===")
