    var minNode: String? = nil
    var minDist = Double.infinity
    for node in graph.nodes {
        if !visited.contains(node) {
            let d = dist[node] ?? Double.infinity
            if d < minDist {
                minDist = d
                minNode = node
            }
        }
    }
    guard let u = minNode else { break }
    if minDist == Double.infinity { break }
    visited.insert(u)

