static const char *parse_string(const char *p, char **out) {
    *out = NULL;
    if (*p != '"') return p;
    p++;
    size_t cap = 64, len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) return p;
    while (*p && *p != '"') {
        char c = *p++;
        if (c == '\\') {
            char e = *p++;
            switch (e) {
                case 'n': c = '\n'; break;
                case 't': c = '\t'; break;
                case 'r': c = '\r'; break;
                case '"': c = '"'; break;
                case '\\': c = '\\'; break;
                case '/': c = '/'; break;
                case 'b': c = '\b'; break;
                case 'f': c = '\f'; break;
                case 'u': p += 4; c = '?'; break;
                default: c = e; break;
            }
        }
        if (len + 1 >= cap) {
            cap *= 2;
            char *nb = (char *)realloc(buf, cap);
            if (!nb) { free(buf); return p; }
            buf = nb;
        }
        buf[len++] = c;
    }
    if (*p == '"') p++;
    buf[len] = '\0';
    *out = buf;
    return p;
