function walk(dir: string, relBase: string, results: FileInfo[]): void {
  let entries: string[];
  try {
    entries = fs.readdirSync(dir);
  } catch {
    return;
  }
  entries.sort();
  for (const name of entries) {
    const absPath = path.join(dir, name);
    const relPath = relBase === '' ? name : relBase + '/' + name;
    let stat: fs.Stats;
    try {
      stat = fs.lstatSync(absPath);
    } catch {
      continue;
    }
    if (stat.isDirectory()) {
      walk(absPath, relPath, results);
    } else if (stat.isFile()) {
      const buf = fs.readFileSync(absPath);
      let lines = 0;
      for (let i = 0; i < buf.length; i++) {
        if (buf[i] === 0x0a) {
          lines++;
        }
      }
      results.push({ relPath, lines, bytes: buf.length });
    }
  }
}

