static char *run_command(const char *command) {
    FILE *fp = popen(command, "r");
    if (!fp) return NULL;

    size_t capacity = 4096;
    size_t length = 0;
    char *buffer = malloc(capacity);
    if (!buffer) {
        pclose(fp);
        return NULL;
    }

    char chunk[1024];
    size_t n;
    while ((n = fread(chunk, 1, sizeof(chunk), fp)) > 0) {
        if (length + n + 1 > capacity) {
            size_t newcap = capacity * 2;
            char *newbuf = realloc(buffer, newcap);
            if (!newbuf) {
                free(buffer);
                pclose(fp);
                return NULL;
            }
            buffer = newbuf;
            capacity = newcap;
        }
        memcpy(buffer + length, chunk, n);
        length += n;
    }
    buffer[length] = '\0';
    pclose(fp);
    return buffer;
}

static void strip_trailing(char *s) {
