func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let n = A.count
    let m = B[0].count
    let p = B.count
    var result = Array(repeating: Array(repeating: 0, count: m), count: n)
    for i in 0..<n {
        for j in 0..<m {
            var sum = 0
            for k in 0..<p {
                sum += A[i][k] * B[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

func determinant(_ M: [[Int]]) -> Int {
    let n = M.count
    if n == 1 { return M[0][0] }
    if n == 2 { return M[0][0] * M[1][1] - M[0][1] * M[1][0] }
    var det = 0
    for j in 0..<n {
        var minor: [[Int]] = []
        for r in 1..<n {
            var row: [Int] = []
            for c in 0..<n {
                if c != j { row.append(M[r][c]) }
            }
            minor.append(row)
        }
        let sign = (j % 2 == 0) ? 1 : -1
        det += sign * M[0][j] * determinant(minor)
    }
    return det
}

func rightJustify(_ v: Int, width: Int) -> String {
    let s = String(v)
    let padding = width - s.count
    var result = ""
    var i = 0
    while i < padding {
        result += " "
        i += 1
    }
    result += s
    return result
}

