fn determinant(m: &[Vec<i64>]) -> i64 {
    let n = m.len();
    if n == 1 {
        return m[0][0];
    }
    if n == 2 {
        return m[0][0] * m[1][1] - m[0][1] * m[1][0];
    }
    let mut det: i64 = 0;
    for col in 0..n {
        let minor: Vec<Vec<i64>> = (1..n)
            .map(|r| {
                m[r]
                    .iter()
                    .enumerate()
                    .filter(|(c, _)| *c != col)
                    .map(|(_, v)| *v)
                    .collect()
            })
            .collect();
        let sign: i64 = if col % 2 == 0 { 1 } else { -1 };
        det += sign * m[0][col] * determinant(&minor);
    }
    det
}

