int main(void) {
    int A[N][N] = {{1,2,3},{4,5,6},{7,8,9}};
    int B[N][N] = {{9,8,7},{6,5,4},{3,2,1}};
    int C[N][N] = {{0}};

    /* Matrix multiplication C = A x B */
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            C[i][j] = 0;
            for (int k = 0; k < N; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    /* Determinant of 3x3 matrix C via cofactor expansion */
    long det = 0;
    det  = (long)C[0][0] * ((long)C[1][1] * C[2][2] - (long)C[1][2] * C[2][1]);
    det -= (long)C[0][1] * ((long)C[1][0] * C[2][2] - (long)C[1][2] * C[2][0]);
    det += (long)C[0][2] * ((long)C[1][0] * C[2][1] - (long)C[1][1] * C[2][0]);

